insert into skill_test_questions
  (id, template_id, question_text, choices, correct_index, points, order_index)
values
  ('676abe6d-b2f9-4f9c-af2b-499bdf08d4ed', '11111111-1111-1111-1111-111111111111', 'What does the === operator check in JavaScript, that == does not?', ARRAY['Value only', 'Value and type', 'Type only', 'Reference equality for all types'], 1, 1, 1),
  ('375f28b2-b8dc-4f27-9540-b72135b72082', '11111111-1111-1111-1111-111111111111', 'What is the output of typeof null in JavaScript?', ARRAY['"null"', '"undefined"', '"object"', '"boolean"'], 2, 1, 2),
  ('5869c7d6-5885-4ce1-9f40-fe542e376edb', '11111111-1111-1111-1111-111111111111', 'Which array method creates a new array with the results of calling a function on every element?', ARRAY['forEach', 'map', 'filter', 'reduce'], 1, 1, 3),
  ('ed9f99b8-5b6d-49ef-9523-4270e4d6b609', '11111111-1111-1111-1111-111111111111', 'What will console.log(typeof NaN) print?', ARRAY['"NaN"', '"undefined"', '"number"', '"object"'], 2, 1, 4),
  ('1d3efbc6-53e9-4443-bfcf-b523e4e919e1', '11111111-1111-1111-1111-111111111111', 'In JavaScript, what does Promise.all() do?', ARRAY['Resolves when the first promise resolves', 'Resolves when all promises resolve, or rejects if any reject', 'Runs promises sequentially', 'Cancels all pending promises'], 1, 1, 5),
  ('d61715fa-8315-41aa-a622-5a7683a22041', '11111111-1111-1111-1111-111111111111', 'What keyword declares a block-scoped variable that cannot be reassigned?', ARRAY['var', 'let', 'const', 'static'], 2, 1, 6),
  ('9a3ddbf7-2455-4101-a262-6867fb0fffb5', '11111111-1111-1111-1111-111111111111', 'What happens when you access a `var` variable before its declaration line runs?', ARRAY['ReferenceError is thrown', 'It is undefined, not an error', 'It always evaluates to null', 'SyntaxError at parse time'], 1, 1, 7),
  ('d3d445c1-ef1b-4a53-8dc3-9ef08f1c8ece', '11111111-1111-1111-1111-111111111111', 'How does an arrow function''s `this` binding differ from a regular function''s?', ARRAY['Arrow functions get their own `this` bound to the global object', 'Arrow functions inherit `this` lexically from their enclosing scope', 'Arrow functions require an explicit `.bind()` to have any `this`', 'There is no difference'], 1, 1, 8),
  ('f05c139b-a9de-4232-a0dd-e959ea943a10', '11111111-1111-1111-1111-111111111111', 'Which array method takes an accumulator and reduces the array to a single value?', ARRAY['map', 'filter', 'reduce', 'some'], 2, 1, 9),
  ('fee5c2ea-ead8-40b7-859e-bf06e912b8c1', '11111111-1111-1111-1111-111111111111', 'What does `JSON.stringify(undefined)` return?', ARRAY['"undefined"', 'null', 'undefined', 'Throws an error'], 2, 1, 10),
  ('2a7ab1ea-7182-45a4-b888-dda5e38615ff', '11111111-1111-1111-1111-111111111111', 'What does `0 ?? ''fallback''` evaluate to, and how does that differ from `0 || ''fallback''`?', ARRAY['Both evaluate to ''fallback''', '?? evaluates to 0 since 0 is not null/undefined; || evaluates to ''fallback'' since 0 is falsy', '?? evaluates to ''fallback''; || evaluates to 0', 'Both evaluate to 0'], 1, 1, 11),
  ('e2f861d8-6405-4925-93e7-89912f8b9d9a', '11111111-1111-1111-1111-111111111111', 'Given `console.log(''a''); setTimeout(() => console.log(''b'')); Promise.resolve().then(() => console.log(''c'')); console.log(''d'');` — what order is logged?', ARRAY['a, b, c, d', 'a, d, c, b', 'a, d, b, c', 'd, a, c, b'], 1, 1, 12),
  ('a97b84a2-4a08-4f45-bdf7-6fe2d28559a7', '22222222-2222-2222-2222-222222222222', 'What does the Python list comprehension [x*2 for x in range(5)] produce?', ARRAY['[0,1,2,3,4]', '[0,2,4,6,8]', '[2,4,6,8,10]', 'A generator object'], 1, 1, 1),
  ('b971ee57-0b2e-49f1-8566-1a79967cf6af', '22222222-2222-2222-2222-222222222222', 'Which keyword is used to define a function in Python?', ARRAY['func', 'def', 'function', 'lambda'], 1, 1, 2),
  ('ebb6eab0-b264-43ba-adb1-d0b2dfafb890', '22222222-2222-2222-2222-222222222222', 'What is the difference between a list and a tuple in Python?', ARRAY['Lists are immutable, tuples are mutable', 'Tuples are immutable, lists are mutable', 'There is no difference', 'Tuples can only hold numbers'], 1, 1, 3),
  ('36540661-fa35-41d7-baf4-73f5518c93d7', '22222222-2222-2222-2222-222222222222', 'What does the self parameter refer to in a Python instance method?', ARRAY['The class itself', 'The instance calling the method', 'A global variable', 'The parent class'], 1, 1, 4),
  ('7170f91c-c892-411e-b523-40097a062eeb', '22222222-2222-2222-2222-222222222222', 'Which of these correctly opens a file for reading and ensures it is closed automatically?', ARRAY['open(''file.txt'', ''r'')', 'with open(''file.txt'', ''r'') as f:', 'file.read(''file.txt'')', 'import file.txt'], 1, 1, 5),
  ('af7328f5-4ba4-411f-a3e4-577e7d8fe2e2', '22222222-2222-2222-2222-222222222222', 'What does *args allow a Python function to accept?', ARRAY['A fixed number of keyword arguments', 'A variable number of positional arguments', 'Only one argument', 'A dictionary of arguments'], 1, 1, 6),
  ('d286e507-7f82-4787-be1d-b333620bd1cc', '22222222-2222-2222-2222-222222222222', 'Which block runs whether or not an exception was raised in the try block?', ARRAY['except', 'else', 'finally', 'raise'], 2, 1, 7),
  ('51555c78-11a6-417c-a830-4086c15d28c1', '22222222-2222-2222-2222-222222222222', 'What does **kwargs allow a Python function to accept?', ARRAY['A variable number of positional arguments', 'A variable number of keyword arguments', 'Only string arguments', 'A fixed set of two arguments'], 1, 1, 8),
  ('445d4f6c-9bca-4d20-a4e7-c022dce7cb97', '22222222-2222-2222-2222-222222222222', 'What does f''{2 + 2}'' evaluate to?', ARRAY['''{2 + 2}''', '''4''', '4', 'SyntaxError'], 1, 1, 9),
  ('ccf507c9-0a14-4fe4-a6e9-4412dd62d2fa', '22222222-2222-2222-2222-222222222222', 'What does my_list[1:3] return, given my_list = [10, 20, 30, 40]?', ARRAY['[10, 20]', '[20, 30]', '[20, 30, 40]', '[30, 40]'], 1, 1, 10),
  ('f6dc650d-9f62-4435-8fec-b4e90338dd1b', '22222222-2222-2222-2222-222222222222', 'What''s the difference between `is` and `==` in Python?', ARRAY['They are always interchangeable', '`is` checks value equality, `==` checks identity', '`is` checks identity (same object), `==` checks value equality', '`is` only works on numbers'], 2, 1, 11),
  ('ddfcbaf3-05f6-41ea-badd-4e23bb4a9f5f', '22222222-2222-2222-2222-222222222222', 'What does calling super().__init__() inside a subclass''s __init__ do?', ARRAY['Creates a new unrelated object', 'Calls the parent class''s constructor', 'Deletes the subclass instance', 'Is only valid in Python 2'], 1, 1, 12),
  ('66f45c6e-8c67-404a-9a59-be9bd3ee2987', '33333333-3333-3333-3333-333333333333', 'Which SQL clause is used to filter rows before grouping?', ARRAY['HAVING', 'WHERE', 'GROUP BY', 'ORDER BY'], 1, 1, 1),
  ('70357c2e-4eff-4732-887d-d4de43ea5692', '33333333-3333-3333-3333-333333333333', 'Which SQL clause filters groups after a GROUP BY?', ARRAY['WHERE', 'HAVING', 'FILTER', 'LIMIT'], 1, 1, 2),
  ('12db9bbc-10ed-4fdf-adc1-6b5a2f017da7', '33333333-3333-3333-3333-333333333333', 'What does an INNER JOIN return?', ARRAY['All rows from both tables', 'Only rows with matching values in both tables', 'All rows from the left table only', 'All rows from the right table only'], 1, 1, 3),
  ('91efbb66-637e-41a0-a03e-7f5bb24ce0e6', '33333333-3333-3333-3333-333333333333', 'Which statement adds a new column to an existing table?', ARRAY['UPDATE TABLE ADD COLUMN', 'ALTER TABLE ... ADD COLUMN', 'CREATE COLUMN', 'INSERT COLUMN'], 1, 1, 4),
  ('a176f0db-39cc-4bf9-bece-6d8bd8479598', '33333333-3333-3333-3333-333333333333', 'What does a PRIMARY KEY constraint guarantee?', ARRAY['Values can repeat but not be null', 'Values are unique and not null', 'The column is indexed but can be null', 'The column stores foreign references only'], 1, 1, 5),
  ('0029df20-1836-4a10-9ece-4377e1122500', '33333333-3333-3333-3333-333333333333', 'Which of these aggregate functions returns the number of rows?', ARRAY['SUM()', 'COUNT()', 'AVG()', 'TOTAL()'], 1, 1, 6),
  ('cb775282-0f13-4974-bbb6-48ba880fe021', '33333333-3333-3333-3333-333333333333', 'What does a LEFT JOIN return that an INNER JOIN would not?', ARRAY['Only matching rows from both tables', 'All rows from the left table, with NULLs where there''s no match on the right', 'All rows from the right table only', 'Rows sorted alphabetically'], 1, 1, 7),
  ('28851c66-44ff-495c-a826-6746b0923d92', '33333333-3333-3333-3333-333333333333', 'What does SELECT DISTINCT do?', ARRAY['Removes duplicate rows from the result set', 'Sorts the result set', 'Filters rows before grouping', 'Adds a new column'], 0, 1, 8),
  ('abd99fc9-dd53-46c7-b9dc-cf8644d679c7', '33333333-3333-3333-3333-333333333333', 'Why does `WHERE column = NULL` never match any rows?', ARRAY['NULL is treated as the string ''NULL''', 'Comparisons with NULL evaluate to unknown, not true — use IS NULL instead', 'It''s a syntax error', 'It matches all rows instead'], 1, 1, 9),
  ('6ae5ff24-b2c7-4bce-b554-621bc5049054', '33333333-3333-3333-3333-333333333333', 'What does GROUP BY do?', ARRAY['Filters individual rows', 'Groups rows sharing the same value(s) so aggregate functions can be applied per group', 'Sorts rows in descending order', 'Removes duplicate columns'], 1, 1, 10),
  ('9d956552-d1e0-427f-9524-b642631fc134', '33333333-3333-3333-3333-333333333333', 'Which clause controls the sort order of a result set, and what keyword sorts it descending?', ARRAY['GROUP BY ... DESC', 'ORDER BY ... DESC', 'HAVING ... DESC', 'WHERE ... DESC'], 1, 1, 11),
  ('8e5662a0-0e45-4bb0-98fb-ae4790f5a72a', '33333333-3333-3333-3333-333333333333', 'How does a UNIQUE constraint differ from a PRIMARY KEY?', ARRAY['They are identical in every way', 'A table can have multiple UNIQUE constraints but only one PRIMARY KEY, and a UNIQUE column may allow a NULL', 'UNIQUE constraints allow duplicate values', 'PRIMARY KEY allows NULL values, UNIQUE does not'], 1, 1, 12)
