-- Seeds the skill_test_* tables (predate the migrations/ convention, so
-- this is the first time their schema and content are captured in the repo).
-- Reproduces exactly what's live: the 3 active, fully-authored "Fundamentals"
-- templates (12 questions each) plus the 9-tier x 16-stack leveled scaffold
-- (144 inactive, content-empty placeholders — see skill-test-level-scaffold
-- in improvements.md) that the level-lock/unlock logic in lib/skill-tests.ts
-- (applyLevelLocks) reasons about via stack + level_order.

create table if not exists skill_test_templates (
  id                    uuid primary key default gen_random_uuid(),
  slug                  text not null unique,
  title                 text not null,
  stack                 text not null,
  description           text not null,
  time_limit_seconds    integer not null,
  is_active             boolean not null default true,
  level                 text,
  level_order           integer,
  target_question_count integer,
  created_at            timestamptz not null default now()
);

create table if not exists skill_test_questions (
  id            uuid primary key default gen_random_uuid(),
  template_id   uuid not null references skill_test_templates(id) on delete cascade,
  question_text text not null,
  choices       text[] not null,
  correct_index integer not null,
  points        integer not null default 1,
  order_index   integer not null,
  created_at    timestamptz not null default now()
);
create index if not exists skill_test_questions_template_idx on skill_test_questions (template_id);

create table if not exists skill_test_attempts (
  id                  uuid primary key default gen_random_uuid(),
  github_id           text not null,
  template_id         uuid not null references skill_test_templates(id) on delete cascade,
  status              text not null default 'in_progress'
                        check (status in ('in_progress', 'completed', 'expired')),
  served_question_ids uuid[] not null,
  answers             jsonb,
  score               integer,
  max_score           integer,
  percentage          integer,
  started_at          timestamptz not null default now(),
  submitted_at        timestamptz
);
create index if not exists skill_test_attempts_github_id_idx on skill_test_attempts (github_id);
create index if not exists skill_test_attempts_template_idx on skill_test_attempts (template_id);

alter table skill_test_templates enable row level security;
alter table skill_test_questions enable row level security;
alter table skill_test_attempts enable row level security;

on conflict (id) do nothing;

on conflict (id) do nothing;

